-- Idempotency key: company_name + job_title + location + application_link.
-- Static values are SQL-escaped by sqlText(); no runtime/user input is executed.

BEGIN;

WITH selected_recruiter AS (
  SELECT r.id AS recruiter_id,
         r.user_id AS created_by_uuid
  FROM public.recruiters r
  WHERE lower(r.email) IN (lower('krishna@rareminds.in'), lower('visakh@rareminds.in'))
     OR lower(r.name) LIKE '%rareminds%'
  ORDER BY
    CASE lower(r.email)
      WHEN lower('krishna@rareminds.in') THEN 0
      WHEN lower('visakh@rareminds.in') THEN 1
      ELSE 2
    END,
    CASE WHEN COALESCE(r.isactive, TRUE) THEN 0 ELSE 1 END,
    r.createdat NULLS LAST,
    r.id
  LIMIT 1
),
owner AS (
  SELECT sr.recruiter_id,
         sr.created_by_uuid,
         COALESCE(
           u."organizationId",
           (
             SELECT o.id
             FROM public.organizations o
             WHERE lower(o.name) = lower('Rareminds')
             ORDER BY o.created_at NULLS LAST, o.id
             LIMIT 1
           )
         ) AS organization_id
  FROM (SELECT 1) anchor
  LEFT JOIN selected_recruiter sr ON TRUE
  LEFT JOIN public.users u ON u.id = sr.created_by_uuid
),
seed_rows (title, company_name, employment_type, location, mode, stipend_or_salary, experience_required, skills_required, description, application_link, deadline, is_active, department, experience_level, salary_range_min, salary_range_max, status, posted_date, requirements, responsibilities, benefits, applications_count, messages_count, views_count, job_title, schedule_note) AS (
